INTRO = "Over coffee after lunch, Seung-chan asks Ye-jin whether Shin Hye-joo knows about Joon-mo's shared apartment, and his relief quickly turns to heartbreak when he hears Hye-joo's new dating rule. Listen to their conversation first."
STORY = [('seungchan', '근데 저 궁금한 게 있는데요.', 'By the way, there is something I am curious about.', [(370, '근데 저 궁금한 게 있는데요')], ''), ('seungchan', '주소 공유 관계에 대해서 혜주 누나는 알고 있나 해서요.', 'I was wondering whether Hye-joo knows about your address-sharing arrangement.', [(372, '주소 공유 관계에 대해서'), (373, '혜주 누나는 알고 있나 해서')], ''), ('yejin', '너 되게 정의롭다. 근데 신경 안 써도 돼.', 'You have quite a sense of justice. But you do not need to worry.', [(379, '너 되게 정의롭다'), (382, '근데 신경 안 써도 돼')], ''), ('yejin', '그 두 사람 이제 더 이상 안 만나.', 'Those two do not see each other anymore.', [(383, '그 두 사람 이제 더 이상 안 만나')], ''), ('seungchan', '네? 몰랐는데 정말 다행입니다.', 'What? I had no idea, what a relief.', [(386, '몰랐는데'), (387, '정말 다행입니다')], ''), ('yejin', '그치, 다행이지? 근데 네가 왜 다행이야?', "Right, it is fortunate, isn't it? Wait, why is it a relief for you?", [(388, '그치 다행이지'), (389, '근데 왜 다행이야')], ''), ('seungchan', '두 분은 순수한 친구 사이신데 오해해서 상처받으면 어쩌나 해서요.', 'Since you two are pure friends, I worried she might misunderstand and get hurt.', [(391, '두 분은 순수한 친구 사이신데'), (393, '오해해서 상처받으면 어쩌나')], ''), ('hyejoo', '어느새 주변에 남자는 피디밖에 없게 된 거예요.', 'Before I knew it, the only men around me were producers.', [(402, '근데 어느새 주변에 남자는'), (402, '없게 된 거예요')], ''), ('yejin', '피디한테 질렸대. 다시는 피디랑 사귀는 일은 없을 거라더라.', 'She said she is sick of producers, and she will never date a producer again.', [(405, '질렸대'), (406, '이제 다시는'), (406, '사귀는 일은 없을 거라더라')], ''), ('yejin', '애가 여리여리하게 생겨 가지고 결단력이 있더라니까.', 'She looks delicate, yet she really has firm resolve.', [(407, '애가 여리여리하게 생겨가지고'), (407, '결단력도 있고')], ''), ('yejin', '승찬이가 혜주 좋아했다니까요. 딱 보면 알지.', 'Seung-chan definitely liked Hye-joo. You can tell at one glance.', [(408, '혜주 좋아했다니까요 딱 보면 알지')], ''), ('yejin', '지는 티 안 내려고 무지 애쓰는데 원래 티가 나는 거예요.', 'He tries hard not to let it show, but feelings like that always show.', [(410, '지는 티 안내려고 무지 애쓰죠'), (411, '원래 그건 티가 나는 거예요')], '')]
OPENER = "Now let's go through it line by line with the English translation."
WALK = [(0, None, "'By the way, there is something I am curious about.'"), (1, None, "'I was wondering whether Hye-joo knows about your address-sharing arrangement.'"), (2, None, "'You have quite a sense of justice. But you do not need to worry.'"), (3, None, "'Those two do not see each other anymore.'"), (4, None, "'What? I had no idea, what a relief.'"), (5, None, "'Right, it is fortunate, isn't it? Wait, why is it a relief for you?'"), (6, None, "'Since you two are pure friends, I worried she might misunderstand and get hurt.'"), (7, None, "'Before I knew it, the only men around me were producers.'"), (8, None, "'She said she is sick of producers, and she will never date a producer again.'"), (9, None, "'She looks delicate, yet she really has firm resolve.'"), (10, None, "'Seung-chan definitely liked Hye-joo. You can tell at one glance.'"), (11, None, "'He tries hard not to let it show, but feelings like that always show.'")]
